const corpo = $json.data ?? $json.body?.data ?? $json.body ?? $json;
if (!corpo || !Array.isArray(corpo.avancos)) throw new Error('Resposta invalida para id_eap ' + $('Loop id_eap (1 por vez)1').item.json.id_eap);

// --- normalizacao: o mesmo payload alimenta Supabase e MySQL ---
const vazio = v => v === null || v === undefined || (typeof v === 'string' && v.trim() === '');
const n = v => { if (vazio(v)) return null; const x = Number(typeof v === 'string' ? v.trim().replace(',', '.') : v); return Number.isFinite(x) ? x : null; };
const s = (v, max) => { if (vazio(v)) return null; const t = String(v).trim(); return t.length > max ? t.slice(0, max) : t; };
const d = v => { if (vazio(v)) return null; const t = String(v).trim().slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(t) ? t : null; };

const dataRef = d($('Loop id_eap (1 por vez)1').item.json.data);
if (!dataRef) throw new Error('Data de referencia invalida: ' + $('Loop id_eap (1 por vez)1').item.json.data);

// os limites de texto abaixo sao o tamanho das colunas em painelmse.eap_apontamentos
const rows = corpo.avancos.map(a => ({
  id: n(a.id),
  id_eap: n(corpo.id_eap ?? $('Loop id_eap (1 por vez)1').item.json.id_eap),
  nome_eap: s(corpo.nome_eap, 120),
  nome_obra: s(corpo.nome_obra, 120),
  data_do_input: dataRef,
  edt: s(a.edt, 60),
  tarefa: s(a.tarefa, 255),
  qtd: n(a.qtd),
  unidade: s(a.unidade, 20),
  avanco_atual: n(a.avanco_atual),
  avanco_atual_p100: n(a.avanco_atual_p100),
  avanco_diario: n(a.avanco_diario),
  meta_diaria: n(a.meta_diaria),
  usuario_avanco_diario: s(a.usuario_avanco_diario, 120),
  status_qualidade: s(a.status_qualidade, 30)
})).filter(r => r.id != null && r.data_do_input != null);

// --- SQL para MySQL: painelmse.eap_apontamentos (PK = id + data_do_input) ---
const MODELO = { id:1, id_eap:1, nome_eap:1, nome_obra:1, data_do_input:1, edt:1, tarefa:1, qtd:1, unidade:1, avanco_atual:1, avanco_atual_p100:1, avanco_diario:1, meta_diaria:1, usuario_avanco_diario:1, status_qualidade:1 };
const CHAVE = ['id', 'data_do_input'];
const q = String.fromCharCode(96);
const COLUNAS = Object.keys(MODELO);
const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\x00/g, '') + "'";
const sqlVal = (v) => (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? String(v) : escapar(v));
const colsSql = COLUNAS.map(c => q + c + q).join(',');
const tuplas = rows.map(l => '(' + COLUNAS.map(c => sqlVal(l[c])).join(',') + ')').join(',\n');
const updSql = COLUNAS.filter(c => !CHAVE.includes(c)).map(c => q + c + q + ' = VALUES(' + q + c + q + ')').join(', ');
const sqlMySql = rows.length ? 'INSERT INTO eap_apontamentos (' + colsSql + ') VALUES ' + tuplas + ' ON DUPLICATE KEY UPDATE ' + updSql : 'SELECT 1';
return [{ json: { rows, sqlMySql, total: rows.length } }];

